/** Move a washed Saturday onto a planted rain-check. Not a new owed week. */

import { byeIsos, rainCheckIsos } from "./calendar";
import { formatLong, parseClock, weekdayName } from "./dates";
import { norm, printName, teamLabel, type League, type PlacedGame, type Washout } from "./model";
import { findField } from "./season-score";

function clockOr(s: string, fallback: number): number {
  let n = parseClock(s) ?? fallback;
  if (n < 7 * 60) n += 12 * 60;
  return n;
}

function dayTitle(iso: string): string {
  const n = weekdayName(iso);
  return n[0].toUpperCase() + n.slice(1);
}

export function canWashDate(league: League, dateIso: string): string | undefined {
  if (byeIsos(league).has(dateIso)) return "Bye — no games to move.";
  if (rainCheckIsos(league).includes(dateIso)) return "That date is already a rain check.";
  return undefined;
}

export function rainHoldReason(league: League, game: PlacedGame, toIso: string): string | undefined {
  const day = weekdayName(toIso);
  const slots = league.preferredSlots.filter((p) => norm(p.bracket) === norm(game.ageGroup));
  const dayOk = day === "saturday" || slots.some((p) => p.day.toLowerCase() === day);
  if (!dayOk) {
    return `${game.ageGroup} has no legal ${dayTitle(toIso)} slot. ${formatLong(toIso)} cannot hold ${game.ageGroup} unless you add one on Preferred slots.`;
  }
  const field = findField(league, game.field);
  if (!field) return undefined;
  const win = field.windows.find((w) => w.day === day);
  if (field.windows.length && !win) {
    return `${game.ageGroup} has no legal ${dayTitle(toIso)} slot. ${formatLong(toIso)} cannot hold ${game.ageGroup} unless you add one on Preferred slots.`;
  }
  const kick = clockOr(game.kickoff, 10 * 60);
  const vacate = clockOr(game.vacate, kick + 60);
  if (win && (kick < win.startMinutes || vacate > win.endMinutes + 5)) {
    return `${game.field} is not open for a ${game.kickoff} kickoff on ${formatLong(toIso)}.`;
  }
  return undefined;
}

export function applyWashout(
  league: League,
  games: PlacedGame[],
  fromIso: string,
  toIso: string,
): { games: PlacedGame[]; washout?: Washout; diagnostics: string[]; moved: number } {
  const blocked = canWashDate(league, fromIso);
  if (blocked) return { games, diagnostics: [blocked], moved: 0 };
  if (!rainCheckIsos(league).includes(toIso)) {
    return { games, diagnostics: [`${formatLong(toIso)} is not a rain-check date on the Season sheet.`], moved: 0 };
  }
  const diagnostics: string[] = [];
  const refused: string[] = [];
  const movedSnap: Washout["moved"] = [];
  const next: PlacedGame[] = [];
  for (const g of games) {
    if (g.dateIso !== fromIso && g.weekIso !== fromIso) {
      next.push(g);
      continue;
    }
    const why = rainHoldReason(league, g, toIso);
    if (why) {
      if (!diagnostics.includes(why)) diagnostics.push(why);
      refused.push(`${g.home} vs ${g.away}`);
      next.push(g);
      continue;
    }
    movedSnap.push({
      home: g.home,
      away: g.away,
      ageGroup: g.ageGroup,
      kickoff: g.kickoff,
      field: g.field,
      campus: g.campus,
      parking: g.parking,
      center: g.center,
    });
    next.push({ ...g, dateIso: toIso, weekIso: toIso });
  }
  if (!movedSnap.length) return { games, diagnostics, moved: 0 };
  diagnostics.push(...rainCoachClashes(league, next, toIso));
  const washout: Washout = { fromIso, toIso, moved: movedSnap, refused };
  return { games: next, washout, diagnostics, moved: movedSnap.length };
}

function clocksOverlap(a: PlacedGame, b: PlacedGame): boolean {
  const a0 = clockOr(a.kickoff, 0);
  const a1 = clockOr(a.vacate, clockOr(a.end, a0 + 50));
  const b0 = clockOr(b.kickoff, 0);
  const b1 = clockOr(b.vacate, clockOr(b.end, b0 + 50));
  return !(a1 <= b0 || b1 <= a0);
}

/** Same clipboard, same rain-check kickoff — the wash does not reset the rule. */
export function rainCoachClashes(league: League, games: PlacedGame[], dateIso: string): string[] {
  const on = games.filter((g) => g.dateIso === dateIso);
  const byCoach = new Map<string, { name: string; first?: string; phone?: string; games: PlacedGame[] }>();
  for (const g of on) {
    for (const lab of [g.home, g.away]) {
      const t = league.teams.find((x) => teamLabel(x) === lab);
      if (!t?.coach) continue;
      const name = printName(t.coach);
      const key = `${name}|${t.coach.phone || ""}`;
      const cur = byCoach.get(key) || { name, first: t.coach.first, phone: t.coach.phone, games: [] };
      if (!cur.games.includes(g)) cur.games.push(g);
      byCoach.set(key, cur);
    }
  }
  const out: string[] = [];
  for (const c of byCoach.values()) {
    if (c.games.length < 2) continue;
    for (let i = 0; i < c.games.length; i++) {
      for (let j = i + 1; j < c.games.length; j++) {
        if (!clocksOverlap(c.games[i], c.games[j])) continue;
        const fields = [c.games[i].field, c.games[j].field].sort();
        const kick = c.games[i].kickoff === c.games[j].kickoff ? c.games[i].kickoff : c.games[i].kickoff;
        const who = c.phone ? `${c.first || c.name.split(" ")[0]} (${c.phone})` : c.name;
        const line = `Broke the camel's back on ${shortMonthDay(dateIso)}: ${who} would have to be on ${fields[0]} and ${fields[1]} at ${kick}.`;
        if (!out.includes(line)) out.push(line);
      }
    }
  }
  return out;
}

export function washCaption(w: Washout): string {
  return `washed out — see ${formatLong(w.toIso).replace(/^[^,]+, /, "")}`;
}

export function shortMonthDay(iso: string): string {
  return formatLong(iso).replace(/^[^,]+, /, "");
}
