<script lang="ts">
  import { formatSheetTime } from "../dates";
  import type { Configuration, League } from "../model";
  import {
    fieldChoices,
    hintFromElement,
    isAwayCampus,
    isDateLead,
    kickoffChoices,
    resolveDrop,
    rowMatchesQuery,
    sheetLines,
    type DropHit,
    type SheetAction,
  } from "../schedule-sheet";

  let {
    league,
    cfg,
    bracket,
    weekIso,
    highlightGame,
    highlightQuery,
    onAction,
  }: {
    league: League;
    cfg: Configuration;
    bracket: string;
    weekIso?: string;
    highlightGame?: string;
    highlightQuery?: string;
    onAction: (a: SheetAction) => void;
  } = $props();

  let host: HTMLDivElement | undefined = $state();
  let draggedId = $state<string | null>(null);
  let dropKind = $state<string>("");

  const lines = $derived(sheetLines(league, cfg.games, bracket, weekIso));
  const times = $derived(kickoffChoices(league, cfg.games, bracket));
  const fields = $derived(fieldChoices(league, cfg.games, bracket));

  $effect(() => {
    if (!host) return;
    host.setAttribute("data-sheet-ready", lines.some((l) => l.kind === "game") ? "yes" : "no");
    host.setAttribute("data-sheet-bracket", bracket);
    host.setAttribute("data-sheet-week", weekIso || "all");
    const hit = host.querySelector<HTMLElement>("[data-hit='yes']");
    hit?.scrollIntoView({ block: "nearest", behavior: "smooth" });
  });

  let drag: {
    pulledId: string;
    pointerId: number;
    ghost: HTMLElement;
  } | null = null;

  function abort() {
    if (!drag || !host) {
      drag = null;
      draggedId = null;
      dropKind = "";
      return;
    }
    drag.ghost.remove();
    host.classList.remove("sheet-dragging");
    host.removeAttribute("data-sheet-dragging");
    host.querySelectorAll(".sheet-drop-target, .sheet-row-lifted").forEach((el) => {
      el.classList.remove("sheet-drop-target", "sheet-row-lifted");
    });
    try {
      host.releasePointerCapture(drag.pointerId);
    } catch {
      /* already released */
    }
    drag = null;
    draggedId = null;
    dropKind = "";
  }

  function paint(hit: DropHit | undefined) {
    if (!host) return;
    host.querySelectorAll(".sheet-drop-target").forEach((el) => el.classList.remove("sheet-drop-target"));
    dropKind = hit?.kind || "";
    if (!hit) return;
    if (hit.kind === "time" && hit.kickoff && !hit.targetId) {
      host.querySelector(`[data-time-slot="${CSS.escape(hit.kickoff)}"]`)?.classList.add("sheet-drop-target");
    } else if (hit.kind === "field" && hit.field && !hit.targetId) {
      host.querySelector(`[data-field-slot="${CSS.escape(hit.field)}"]`)?.classList.add("sheet-drop-target");
    } else if (hit.targetId) {
      const row = host.querySelector(`[data-game="${CSS.escape(hit.targetId)}"]`);
      row?.classList.add("sheet-drop-target");
      if (hit.kind === "time") row?.querySelector('[data-drop="time"]')?.classList.add("sheet-drop-target");
      if (hit.kind === "field") row?.querySelector('[data-drop="field"]')?.classList.add("sheet-drop-target");
    }
  }

  function under(e: PointerEvent) {
    return hintFromElement(document.elementFromPoint(e.clientX, e.clientY));
  }

  function onPointerDown(e: PointerEvent) {
    if (e.button !== 0 || !host) return;
    const row = (e.target as HTMLElement | null)?.closest?.("[data-sheet-row][data-game]") as HTMLElement | null;
    if (!row) return;
    const pulledId = row.getAttribute("data-game");
    if (!pulledId) return;
    e.preventDefault();
    abort();
    row.classList.add("sheet-row-lifted");
    const ghost = document.createElement("div");
    ghost.setAttribute("data-sheet-ghost", "yes");
    ghost.className = "sheet-ghost";
    const home = row.getAttribute("data-home") || "";
    const away = row.getAttribute("data-away") || "";
    const time = row.querySelector('[data-col="time"]')?.textContent || "";
    const loc = row.querySelector('[data-col="location"]')?.textContent || "";
    ghost.innerHTML = `<strong>${time}</strong> ${home} vs ${away} <span>${loc}</span>`;
    ghost.style.width = `${Math.min(row.getBoundingClientRect().width, 420)}px`;
    document.body.appendChild(ghost);
    host.classList.add("sheet-dragging");
    host.setAttribute("data-sheet-dragging", "yes");
    drag = { pulledId, pointerId: e.pointerId, ghost };
    draggedId = pulledId;
    try {
      host.setPointerCapture(e.pointerId);
    } catch {
      /* headless still delivers move/up */
    }
    ghost.style.left = `${e.clientX + 12}px`;
    ghost.style.top = `${e.clientY - 10}px`;
  }

  function onPointerMove(e: PointerEvent) {
    if (!drag) return;
    drag.ghost.style.left = `${e.clientX + 12}px`;
    drag.ghost.style.top = `${e.clientY - 10}px`;
    paint(resolveDrop(drag.pulledId, under(e)));
  }

  function finish(e: PointerEvent) {
    if (!drag) return;
    const pulledId = drag.pulledId;
    const hit = resolveDrop(pulledId, under(e));
    abort();
    if (!hit) return;
    const pulled = cfg.games.find((g) => g.id === pulledId);
    if (!pulled) return;
    if (hit.kind === "swap" && hit.targetId) {
      const target = cfg.games.find((g) => g.id === hit.targetId);
      if (target) onAction({ type: "swap", pulled, target });
      return;
    }
    if (hit.kind === "time" && hit.kickoff) {
      if (pulled.kickoff === hit.kickoff && (!hit.dateIso || hit.dateIso === pulled.dateIso)) return;
      onAction({ type: "time", game: pulled, kickoff: hit.kickoff, dateIso: hit.dateIso });
      return;
    }
    if (hit.kind === "field" && hit.field) {
      if (pulled.field === hit.field) return;
      onAction({ type: "field", game: pulled, field: hit.field });
    }
  }

  function onKey(e: KeyboardEvent) {
    if (e.key === "Escape") abort();
  }
</script>

<svelte:window onkeydown={onKey} />

<div
  class="sheet-stage"
  role="application"
  data-sheet-host
  data-sheet-bracket={bracket}
  data-sheet-week={weekIso || "all"}
  data-drop-kind={dropKind}
  data-sheet-ready={lines.some((l) => l.kind === "game") ? "yes" : "no"}
  bind:this={host}
  onpointerdown={onPointerDown}
  onpointermove={onPointerMove}
  onpointerup={finish}
  onpointercancel={abort}
>
  <div class="sheet-rails" data-sheet-rails>
    <div class="sheet-rail" data-time-rail>
      <span class="rail-label">Time</span>
      {#each times as t (t)}
        <button type="button" class="chip" data-time-slot={t}>{formatSheetTime(t)}</button>
      {/each}
    </div>
    <div class="sheet-rail" data-field-rail>
      <span class="rail-label">Field</span>
      {#each fields as f (f.name + f.campus)}
        <button type="button" class="chip" data-field-slot={f.name} data-campus={f.campus}>{f.label}</button>
      {/each}
    </div>
  </div>

  <div class="sheet-scroll">
    <table class="season-grid" data-season-grid>
      <thead>
        <tr>
          <th data-col="date">DATE</th>
          <th data-col="time">TIME</th>
          <th data-col="home">HOME</th>
          <th data-col="away">AWAY</th>
          <th data-col="location">LOCATION</th>
        </tr>
      </thead>
      <tbody>
        {#each lines as line, i (line.kind === "break" ? `b-${line.dateIso}-${i}` : line.row.id)}
          {#if line.kind === "break"}
            <tr class="sheet-date-break" data-date-break={line.dateIso}>
              <td colspan="5"></td>
            </tr>
          {:else}
            {@const row = line.row}
            {@const prev = i > 0 ? lines[i - 1] : undefined}
            {@const lead = isDateLead(row.dateIso, prev && prev.kind === "game" ? prev.row.dateIso : "")}
            {@const hit = rowMatchesQuery(row, highlightQuery, highlightGame)}
            <tr
              class="sheet-row"
              class:sheet-row-lifted={draggedId === row.id}
              data-sheet-row
              data-game={row.id}
              data-week={row.dateIso}
              data-bracket={row.bracket}
              data-home={row.homeLabel}
              data-away={row.awayLabel}
              data-location={row.location}
              data-away-campus={isAwayCampus(row.location) ? "yes" : "no"}
              data-time={row.time}
              data-kickoff={row.kickoff}
              data-field={row.field}
              data-street={row.street || undefined}
              data-hit={hit ? "yes" : "no"}
            >
              <td data-col="date" data-date-lead={lead ? "yes" : "no"}>
                <span data-grip aria-hidden="true">⠿</span>
                {row.date}
              </td>
              <td
                data-col="time"
                data-drop="time"
                data-game={row.id}
                data-kickoff={row.kickoff}
                data-week={row.dateIso}
              >
                {row.time}
              </td>
              <td data-col="home">{row.home}</td>
              <td data-col="away">{row.away}</td>
              <td
                data-col="location"
                data-drop="field"
                data-game={row.id}
                data-field={row.field}
                data-away-campus={isAwayCampus(row.location) ? "yes" : "no"}
                title={row.street || undefined}
                data-street={row.street || undefined}
              >
                {row.location}
              </td>
            </tr>
          {/if}
        {/each}
        {#if !lines.length}
          <tr>
            <td class="sheet-empty" colspan="5">No games in this bracket.</td>
          </tr>
        {/if}
      </tbody>
    </table>
  </div>
</div>
