/** Season file: a real SQLite database the commissioner carries between laptops. */

import initSqlJs, { type Database, type SqlJsStatic } from "sql.js";
import type { Configuration, League, SeasonState } from "./model";

let SQL: SqlJsStatic | null = null;

async function engine(): Promise<SqlJsStatic> {
  if (SQL) return SQL;
  SQL = await initSqlJs({
    locateFile: (f) => (typeof window !== "undefined" ? `/${f}` : `${process.cwd()}/public/${f}`),
  });
  return SQL;
}

function schema(db: Database) {
  db.run(`
    CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT);
    CREATE TABLE IF NOT EXISTS league (id INTEGER PRIMARY KEY, json TEXT NOT NULL);
    CREATE TABLE IF NOT EXISTS configurations (
      id TEXT PRIMARY KEY,
      name TEXT,
      created_at TEXT,
      json TEXT NOT NULL
    );
  `);
}

export async function saveSeasonFile(state: SeasonState): Promise<Uint8Array> {
  const sql = await engine();
  const db = new sql.Database();
  schema(db);
  db.run("INSERT OR REPLACE INTO meta VALUES (?, ?)", ["product", "Van Season"]);
  db.run("INSERT OR REPLACE INTO meta VALUES (?, ?)", ["savedAt", new Date().toISOString()]);
  if (state.publishedId) db.run("INSERT OR REPLACE INTO meta VALUES (?, ?)", ["published", state.publishedId]);
  if (state.league) {
    db.run("INSERT INTO league (json) VALUES (?)", [JSON.stringify(state.league)]);
  }
  for (const c of state.configurations) {
    db.run("INSERT INTO configurations (id, name, created_at, json) VALUES (?, ?, ?, ?)", [
      c.id,
      c.name,
      c.createdAt,
      JSON.stringify(c),
    ]);
  }
  const bytes = db.export();
  db.close();
  return bytes;
}

export async function loadSeasonFile(data: Uint8Array): Promise<SeasonState> {
  const sql = await engine();
  const db = new sql.Database(data);
  schema(db);
  let league: League | null = null;
  const leagueRows = db.exec("SELECT json FROM league ORDER BY id DESC LIMIT 1");
  if (leagueRows[0]?.values[0]?.[0]) {
    league = JSON.parse(String(leagueRows[0].values[0][0])) as League;
  }
  const configurations: Configuration[] = [];
  const cfgRows = db.exec("SELECT json FROM configurations");
  if (cfgRows[0]) {
    for (const row of cfgRows[0].values) {
      configurations.push(JSON.parse(String(row[0])) as Configuration);
    }
  }
  let publishedId: string | undefined;
  const pub = db.exec("SELECT value FROM meta WHERE key = 'published'");
  if (pub[0]?.values[0]?.[0]) publishedId = String(pub[0].values[0][0]);
  db.close();
  return { league, configurations, publishedId, lastSourceName: league?.sourceName };
}

export function seasonFilename(league: League | null): string {
  if (league?.sourceName) {
    return league.sourceName.replace(/\.xlsx$/i, ".sqlite");
  }
  return "VSA-Fall-2026.sqlite";
}
